 CREATE VIEW Vue_Dailyinout as   SELECT     '2' AS Trn, Trs_Del1.Prs_Dept, Trs_Del1.Dt, RTRIM(Trs_Del1.DocNo) + '/' + RTRIM(Trs_Del1.Finyear) AS Doc, case when  Trs_Del1.Party =0 then Trs_Del1.Buyer else Trs_Del1.party end  as Party, Trs_Del2.OrdId,Trs_Del2.StyleNo, Trs_Del2.BgRl, Trs_Del2.Kg As Kg,Trs_Del2.mtr, '' AS Pdcref, CASE WHEN trtype = 1 THEN CASE WHEN isnull(Trs_Del1.ProcessType, 'P') = 'P' THEN  'Process Issue' ELSE 'Re-Process Issue' END WHEN trtype = 4 THEN 'Purchase Return' WHEN trtype = 12 THEN 'Acc.DirectReceipt Return' WHEN trtype = 6 THEN 'Acc.Purch.Return' WHEN trtype = 7 THEN 'Acc.Issue' WHEN trtype = 13 THEN 'Party Rejection Return' WHEN trtype = 10 AND isnull(ProcessType, 'P') = 'P' THEN 'Acc.Process Issue' WHEN trtype = 10 AND ProcessType = 'R' THEN  'Acc.Reprocess Issue' WHEN trtype = 11 THEN 'DirectReceipt Return' WHEN trtype = 14 THEN 'Godown Transfer' WHEN trtype = 15 THEN  'Godown Transfer Acc' END AS trs, Trs_Del1.ID, Trs_Del1.Coycode, ISNULL(Mas_Count.CountName, '') AS Countname, Case when Prs_dept=8 then ISNULL(Mas_Color.ColorDesc, '') ELSE ISNULL(Mas_Color_1.ColorDesc, '') END AS Color, ISNULL(Mas_Mill.ShortMill, '') AS Mill, ISNULL(Mas_Fabric.Fabdesc, '') AS Fabdesc,ISNULL(Mas_Fabric.Fabid, '') AS Fabid, StockTable.Gsm, StockTable.GG, StockTable.ll, ISNULL(Mas_Dia.Dia, '') AS Dia, ISNULL(Mas_Acc.Acc_Descr, '') AS Acc_Descr, ISNULL(Mas_AccDes.AccDescription, '') AS AccDescription, ISNULL(Mas_Size.SizeDesc, '') AS SizeDesc, StockTable.LotNo, StockTable.YF, ISNULL(OrdSizeMas.SNo, 0) AS SIZSLNO, '' AS OrdRef, '' AS GenItem, '' AS GenUOM, ISNULL(Trs_Del1.ProcessType, 'P') AS ProcessType, Trs_Del1.PartyUnit, ISNULL(Trs_Del1.GPNo, 0) AS GpNo,  case when Trs_Del1.Party =0 then 'Buyer' else 'Party' end AS PartyBuyer, Isnull(Mas_Design.DesignDesc,'') As DesignDesc,0 As BalKgs,0 As BalPer,IsNull(remark,'') As Remark,0 as targetstageid FROM  Mas_Design RIGHT OUTER JOIN  Trs_Del1 INNER JOIN Trs_Del2 ON Trs_Del1.ID = Trs_Del2.ID INNER JOIN StockTable ON Trs_Del2.StockID =  StockTable.StockID ON Mas_Design.DesignId = StockTable.PRINT_DESIGNID LEFT OUTER JOIN OrdSizeMas RIGHT OUTER JOIN Mas_Size ON  OrdSizeMas.SizeID = Mas_Size.SizeID ON StockTable.OrdID = OrdSizeMas.OrdID AND StockTable.Siz = Mas_Size.SizeID and  OrdSizeMas.StyleNo=Trs_Del2.StyleNo LEFT OUTER JOIN Mas_AccDes ON StockTable.Ades = Mas_AccDes.ID LEFT OUTER JOIN Mas_Acc ON  StockTable.Atype = Mas_Acc.ID LEFT OUTER JOIN Mas_Dia ON StockTable.DiaID = Mas_Dia.DiaID LEFT OUTER JOIN Mas_Fabric ON  StockTable.FabID = Mas_Fabric.FabID LEFT OUTER JOIN Mas_Mill ON StockTable.MillID = Mas_Mill.MillID LEFT OUTER JOIN Mas_Color ON  Trs_del1.DyeColID = Mas_Color.ColID LEFT OUTER JOIN Mas_Color as Mas_Color_1 ON StockTable.ColID = Mas_Color_1.ColID  LEFT OUTER JOIN Mas_Count ON StockTable.CntID = Mas_Count.CountID WHERE     (Trs_Del1.TrType <> 3) AND (Trs_Del1.TrType <> 8)  AND (Trs_Del1.TrType <> 9) AND (Trs_Del1.TrType <> 5)  /*comment break*/  UNION ALL  SELECT     '1' AS Trn, Trs_Grn1.Dept , Trs_Grn1.dt, RTRIM(Trs_Grn1.DocNo) + '/' + RTRIM(Trs_Grn1.Finyear) AS Doc, case   when Trs_Grn1.SuppID =0 then Trs_Grn1.Buyer Else Trs_Grn1.SuppID End As SuppId,StockTable_2.OrdID,Trs_GRN2.StyleNo, Trs_GRN2.RBag, Trs_GRN2.RecKgs, Trs_GRN2.Recmtr, Trs_Grn1.PartyDCref, CASE WHEN isnull(Trs_Grn1.ProcessType, 'P') = 'P' THEN + GrnType + ' Receipt' ELSE 'Re-Process Receipt' END as trs, Trs_Grn1.ID, Trs_Grn1.Coycode, ISNULL(Mas_Count_2.CountName, '')  AS CountName, ISNULL(Mas_Color_5.ColorDesc, '') AS ColorDesc, ISNULL(Mas_Mill_2.ShortMill, '') AS Mill,  ISNULL(Mas_Fabric_2.Fabdesc, '') AS Fabdesc, ISNULL(Mas_Fabric_2.Fabid, '') AS Fabid,StockTable_2.Gsm,StockTable_2.GG, StockTable_2.ll, ISNULL(Mas_Dia_2.Dia,'') AS Dia, ISNULL(Mas_Acc_2.Acc_Descr,'') AS Acc_Descr, ISNULL(Mas_AccDes_2.AccDescription,'') AS AccDescription, ISNULL(Mas_Size_5.SizeDesc, '') AS SizeDesc,StockTable_2.LotNo, StockTable_2.YF, ISNULL(OrdSizeMas_5.SNo, 0) AS SIZSNO, '' AS OrdRef, '' AS GenItem, '' AS GenUOM, trs_grn1.processtype, 'P' AS Expr1, 0 AS GpNo, case when Trs_Grn1.SuppID =0 then  'Buyer' else 'Party' end AS PartyBuyer,Isnull(Mas_Design.DesignDesc,'') As DesignDesc,Case When Mas_Dept.RecMethod='D' Then  IsNull(Vue_DailyInOutBalance.BalKgs,0) Else IsNull(Vue_DailyInOutOrdBalance.BalKgs,0) End As BalKgs,Case When Mas_Dept.RecMethod='D' Then IsNull(Vue_DailyInOutBalance.BalPer,0) Else IsNull(Vue_DailyInOutOrdBalance.BalPer,0) End As BalPer,IsNull(remark,'') As Remark ,0 as targetstageid FROM Mas_Design RIGHT OUTER JOIN Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN StockTable AS StockTable_2 ON Trs_GRN2.StockID =  StockTable_2.StockID ON  Mas_Design.DesignId = StockTable_2.PRINT_DESIGNID  LEFT OUTER JOIN OrdSizeMas AS OrdSizeMas_5 INNER JOIN Mas_Size AS Mas_Size_5 ON OrdSizeMas_5.SizeID = Mas_Size_5.SizeID ON   StockTable_2.OrdID = OrdSizeMas_5.OrdID And StockTable_2.Siz = Mas_Size_5.SizeID And OrdSizeMas_5.StyleNo = Trs_GRN2.StyleNo  LEFT OUTER JOIN Mas_AccDes AS Mas_AccDes_2 ON StockTable_2.Ades = Mas_AccDes_2.ID LEFT OUTER JOIN Mas_Acc AS Mas_Acc_2 ON   StockTable_2.Atype = Mas_Acc_2.ID LEFT OUTER JOIN Mas_Dia AS Mas_Dia_2 ON StockTable_2.DiaID = Mas_Dia_2.DiaID LEFT OUTER JOIN  Mas_Fabric AS Mas_Fabric_2 ON StockTable_2.FabID = Mas_Fabric_2.FabID LEFT OUTER JOIN Mas_Mill AS Mas_Mill_2 ON StockTable_2.MillID = Mas_Mill_2.MillID LEFT OUTER JOIN Mas_Color AS Mas_Color_5  ON StockTable_2.ColID = Mas_Color_5.ColID LEFT OUTER JOIN Mas_Count AS  Mas_Count_2 ON StockTable_2.CntID = Mas_Count_2.CountID LEFT OUTER JOIN Mas_Dept ON Trs_Grn1.Dept = Mas_Dept.DeptId Left Join  Vue_DailyInOutBalance ON Trs_Grn1.DcId = Vue_DailyInOutBalance.DcId Left Join Vue_DailyInOutOrdBalance ON Trs_Grn2.OrdId = Vue_DailyInOutOrdBalance.DcId And Trs_Grn1.Dept = Vue_DailyInOutOrdBalance.DeptId And Trs_Grn1.SuppId = Vue_DailyInOutOrdBalance.PartyId /*comment break*/  UNION ALL   SELECT '2' AS Trn, ISNULL(Trs_Pcs1.Dept, 0) AS Dept, Trs_Pcs1.dtDCDate, RTRIM(Trs_Pcs1.DocNo) + '/' + RTRIM(Trs_Pcs1.Finyear) AS DocNo, case Trs_pcs1.Deltype when 'Unit Transfer' then Trs_Pcs1.ToCoyCode when 'Despatch' then  Trs_Pcs1.Buyer else Trs_Pcs1.Party end Party, Trs_Pcs1.Ordjobno,Trs_Pcs2.StyleNo, Trs_Pcs2.Pcs AS Bags, 0 As Kgs, 0 AS Pcs, '' AS  Pdcref,case  Trs_Pcs1.DelType when 'Process' then case  Isnull(processtype,'P') when 'P'  then 'Process' when   'R' then 'ReProcess'  end  else Trs_Pcs1.DelType end AS Trs, Trs_Pcs1.ID, Trs_Pcs1.Coycode, ISNULL(Mas_Color_4.ColorDesc, '') AS Countname,  ISNULL(Mas_StyleDesc.StyleDesc, '') AS Color, ISNULL(Mas_Panel.PanelName, '') AS Mill, '' AS Fabdesc,0 as fabid, 0 AS Gsm, 0 AS GG, '' AS LL, Mas_Size_4.SizeDesc AS Dia, '' AS Acc_Descr, '' AS AccDescription, '' AS SizeDesc, '' AS LotNo, 'P' AS YF, ISNULL(OrdSizeMas_4.SNo, 0) AS SSNo, '' AS OrdRef, '' AS GenItem, '' AS GenUOM, isnull(processtype,'P') as ProcessType, case Trs_pcs1.Deltype when 'Unit Transfer' then 'U' else 'P' end PartyUnit,Isnull(GpNo,0) GpNo, IsNull(Delivery_To_Flg,'Party') as  PartyBuyer,''  As DesignDesc,0 As BalKgs,0 As BalPer,IsNull(remark,'') As Remark,targetstageid FROM Mas_Color AS Mas_Color_4  RIGHT OUTER JOIN Mas_Size AS Mas_Size_4 INNER JOIN OrdSizeMas AS OrdSizeMas_4 ON Mas_Size_4.SizeID = OrdSizeMas_4.SizeID RIGHT OUTER  JOIN Trs_Pcs1 INNER JOIN Trs_Pcs2 ON Trs_Pcs1.ID = Trs_Pcs2.ID ON Mas_Size_4.SizeID = Trs_Pcs2.SizeID AND OrdSizeMas_4.OrdID =  Trs_Pcs1.Ordjobno and OrdSizeMas_4.StyleNo=Trs_Pcs2.StyleNo LEFT OUTER JOIN Mas_Panel ON Trs_Pcs2.PanelID = Mas_Panel.PanelID  LEFT OUTER JOIN Mas_StyleDesc ON Trs_Pcs2.StyleID = Mas_StyleDesc.StyleID ON Mas_Color_4.ColID = Trs_Pcs2.ColID  /*comment break*/  UNION ALL   SELECT '1' AS Trn, ISNULL(Trs_PcsGrn1.Dept, 0) AS Expr1, Trs_PcsGrn1.Dt, RTRIM(Trs_PcsGrn1.Docno) + '/' +  RTRIM(Trs_PcsGrn1.Finyear) AS Doc, Trs_PcsGrn1.Party, Trs_PcsGrn1.OrdJob,Trs_PcsGrn2.StyleNo, Trs_PcsGrn2.RecPcs, 0 As Kgs, 0 AS Mtr,  Trs_PcsGrn1.Partydcref, Trs_PcsGrn1.GrnType, Trs_PcsGrn1.ID, Trs_PcsGrn1.Coycode, ISNULL(Mas_Color_1.ColorDesc,'') AS ColorDesc, Mas_StyleDesc_1.StyleDesc AS Color, ISNULL(Mas_Panel_1.PanelName, '') AS Mill, '' AS Fabdesc,0 as fabid, 0 AS Expr2, 0 AS Expr3,  '' AS Expr4, Mas_Size_1.SizeDesc AS Dia, '' AS Acc_Descr, '' AS AccDes, '' AS  SizeDesc, '' AS Expr5, 'P' AS Expr6, ISNULL(OrdSizeMas_1.SNo, 0) AS SSNo, '' AS OrdRef, '' AS GenItem, '' AS GenUOM, '' as ProcessType,'P' as PartyUnit, 0 as GpNo,  'Party' as PartyBuyer,''  As DesignDesc,0 As BalKgs,0 As BalPer,IsNull(remark,'') As Remark,targetstageid  FROM OrdSizeMas AS  OrdSizeMas_1 INNER JOIN  Mas_Size AS Mas_Size_1 ON OrdSizeMas_1.SizeID = Mas_Size_1.SizeID RIGHT OUTER JOIN Trs_PcsGrn1 INNER JOIN  Trs_PcsGrn2 ON Trs_PcsGrn1.ID = Trs_PcsGrn2.ID ON OrdSizeMas_1.OrdID = Trs_PcsGrn1.OrdJob AND Mas_Size_1.SizeID = Trs_PcsGrn2.SizID   and OrdSizeMas_1.StyleNo=Trs_PcsGrn2.StyleNo LEFT OUTER JOIN Mas_Panel AS Mas_Panel_1 ON Trs_PcsGrn2.PanelID = Mas_Panel_1.PanelID   LEFT OUTER JOIN Mas_StyleDesc AS Mas_StyleDesc_1 ON Trs_PcsGrn2.StyleID = Mas_StyleDesc_1.StyleID LEFT OUTER JOIN Mas_Color AS  Mas_Color_1 ON Trs_PcsGrn2.ColID = Mas_Color_1.ColId  /*comment break*/   UNION ALL   SELECT '2' AS Trn, 0 AS Dept, Trs_Gen1.Dt, RTRIM(CAST(Trs_Gen1.Dcno AS varchar)) + '/' + Trs_Gen1.Finyear AS Doc,  Trs_Gen1.PartyID, 0 AS Ordid,'' as styleno, 0 AS Rolls, 0 AS mtr, Trs_Gen2.DelQty AS Kgs,'' AS PartyDc, CASE dctype WHEN 'R'  THEN 'GENERAL - RETURNABLE' ELSE 'GENERAL - NON RETURNABLE' END AS DelType,Trs_Gen1.ID,Trs_Gen1.coycode, '' AS COUNT, '' AS color,  '' AS mill, '' AS fab,0 as fabid, 0 AS Gsm, 0 AS GG, '' AS LL, '' AS dia, '' AS Acc_Descr, '' AS AccDes, '' AS SizeDesc, '' AS Lotno,  'G ' AS YF, 0 AS Expr1,Trs_Gen1.OrdRef, Trs_Gen2.ItemDesc, Mas_Uom.Uom, '' as ProcessType,'P' as PartyUnit, Isnull(Gpno,0) GpNo,  'Party' as PartyBuyer,''  As DesignDesc,0 As BalKgs,0 As BalPer,IsNull(remark,'') As Remark,0 as targetstageid FROM Trs_Gen1  INNER JOIN Trs_Gen2 ON Trs_Gen1.ID= Trs_Gen2.Id LEFT OUTER JOIN Mas_Uom ON Trs_Gen2.UomID = Mas_Uom.UomID  /*comment break*/   UNION ALL  SELECT '1' AS Trn, 0 AS Dept, Trs_GenGrn1.GRNdt, RTRIM(Trs_GenGrn1.GrnNo) + '/' + Trs_GenGrn1.Finyear AS Doc, Trs_GenGrn1.PartyID, 0 AS Ordid,'' as styleno, 0 AS Rolls, 0 AS mtr,Trs_Gengrn2.RecdQty, Trs_GenGrn1.PartyDcref, CASE cat WHEN 1 THEN 'GENERAL - DELIVERED GOODS' when 2 then 'GENERAL - DIRECT GOODS'   ELSE 'GENERAL -RETURNABLE GOODS' END AS type, Trs_GenGrn1.ID, Trs_GenGrn1.Coycode, '' AS PartyDc, '' AS color, '' AS mill, '' AS fab,0 as fabid, 0 AS Gsm, 0 AS GG, '' AS LL, '' AS dia, '' AS  Acc_Descr, '' AS AccDes, '' AS SizeDesc, '' AS Lotno, 'G' AS YF, 0 AS Expr1, Trs_GenGrn1.Orderref,Trs_Gengrn2.Itemdes, Mas_Uom_1.Uom,  '' as ProcessType,'P' as PartyUnit, 0 as GpNo, 'Party' as PartyBuyer,''  As DesignDesc,0 As BalKgs,0 As BalPer,IsNull(remark,'') As Remark,0 as targetstageid FROM Trs_GenGrn1 INNER JOIN Trs_Gengrn2 ON Trs_GenGrn1.ID = Trs_Gengrn2.ID LEFT OUTER JOIN Mas_Uom AS  Mas_Uom_1 ON Trs_Gengrn2.UomId = Mas_Uom_1.UomID/*comment break*/  UNION ALL  SELECT     '1' AS Trn, Trs_MultiPrs_Grn3.DeptID, Trs_MultiPrs_Grn1.GRNDate, 'X' +RTRIM(Trs_MultiPrs_Grn1.DocNo) + '/' +  RTRIM(Trs_MultiPrs_Grn1.Finyear) AS Doc,  Trs_MultiPrs_Grn2.PartyID  As SuppId,StockTable_2.OrdID,Trs_MultiPrs_Grn3.StyleNo,  Sum(Trs_MultiPrs_Grn3.RBag) as RBag, Sum(Trs_MultiPrs_Grn3.RecKgs) as RecKgs, Sum(Trs_MultiPrs_Grn3.Recmtr) AS RecMtr, Trs_MultiPrs_Grn2.PartyDCref, CASE WHEN isnull(Trs_MultiPrs_Grn1.ProcessType, 'P') = 'P' THEN + GrnType + ' Receipt' ELSE 'Re-Process Receipt' END as trs, Trs_MultiPrs_Grn1.ID, Trs_MultiPrs_Grn1.Coycode, ISNULL(Mas_Count_2.CountName, '')  AS CountName, ISNULL(Mas_Color_5.ColorDesc, '') AS ColorDesc, ISNULL(Mas_Mill_2.ShortMill, '') AS Mill,  ISNULL(Mas_Fabric_2.Fabdesc, '') AS Fabdesc, ISNULL(Mas_Fabric_2.Fabid, '') AS Fabid,StockTable_2.Gsm,StockTable_2.GG, StockTable_2.ll, ISNULL(Mas_Dia_2.Dia,'') AS Dia, '' AS Acc_Descr, '' AS AccDescription, ISNULL(Mas_Size_5.SizeDesc, '') AS SizeDesc,StockTable_2.LotNo, StockTable_2.YF, ISNULL(OrdSizeMas_5.SNo, 0) AS  SIZSNO, '' AS OrdRef, '' AS GenItem, '' AS GenUOM, Trs_MultiPrs_Grn1.processtype, 'P' AS Expr1, 0 AS GpNo, case when Trs_MultiPrs_Grn2.PartyID =0 then  'Buyer' else 'Party' end AS PartyBuyer,Isnull(Mas_Design.DesignDesc,'') As DesignDesc,Case When Mas_Dept.RecMethod='D' Then  Sum(IsNull(Vue_DailyInOutBalance.BalKgs,0)) Else Sum(IsNull(Vue_DailyInOutOrdBalance.BalKgs,0)) End As BalKgs,Case When Mas_Dept.RecMethod='D'  Then Sum(IsNull(Vue_DailyInOutBalance.BalPer,0)) Else Sum(IsNull(Vue_DailyInOutOrdBalance.BalPer,0)) End As BalPer,IsNull(remark,'') As Remark ,0 as targetstageid FROM Mas_Design RIGHT OUTER JOIN Trs_MultiPrs_Grn1 INNER JOIN Trs_MultiPrs_Grn2 ON Trs_MultiPrs_Grn2.ID = Trs_MultiPrs_Grn1.ID  INNER JOIN Trs_MultiPrs_Grn3 ON Trs_MultiPrs_Grn1.ID=Trs_MultiPrs_Grn3.ID And Trs_MultiPrs_Grn2.DeptiD=Trs_MultiPrs_Grn3.DeptID  INNER JOIN StockTable AS StockTable_2 ON Trs_MultiPrs_Grn3.StockID =  StockTable_2.StockID ON  Mas_Design.DesignId =  StockTable_2.PRINT_DESIGNID LEFT OUTER JOIN OrdSizeMas AS OrdSizeMas_5 INNER JOIN Mas_Size AS Mas_Size_5 ON OrdSizeMas_5.SizeID =  Mas_Size_5.SizeID ON StockTable_2.OrdID = OrdSizeMas_5.OrdID AND  StockTable_2.Siz = Mas_Size_5.SizeID and OrdSizeMas_5.StyleNo= Trs_MultiPrs_Grn3.StyleNo  LEFT OUTER JOIN Mas_Dia AS Mas_Dia_2 ON StockTable_2.DiaID = Mas_Dia_2.DiaID LEFT OUTER JOIN  Mas_Fabric AS Mas_Fabric_2 ON StockTable_2.FabID = Mas_Fabric_2.FabID LEFT OUTER JOIN Mas_Mill AS Mas_Mill_2 ON StockTable_2.MillID =  Mas_Mill_2.MillID LEFT OUTER JOIN Mas_Color AS Mas_Color_5  ON StockTable_2.ColID = Mas_Color_5.ColID LEFT OUTER JOIN Mas_Count AS  Mas_Count_2 ON StockTable_2.CntID = Mas_Count_2.CountID LEFT OUTER JOIN Mas_Dept ON Trs_MultiPrs_Grn2.DeptID = Mas_Dept.DeptId Left Join  Vue_DailyInOutBalance ON Trs_MultiPrs_Grn2.OurDCID = Vue_DailyInOutBalance.DcId Left Join Vue_DailyInOutOrdBalance ON  Trs_MultiPrs_Grn3.OrdId =  Vue_DailyInOutOrdBalance.DcId And Trs_MultiPrs_Grn3.DeptID = Vue_DailyInOutOrdBalance.DeptId And Trs_MultiPrs_Grn2.PartyID = Vue_DailyInOutOrdBalance.PartyId Where Isnull(FinalProcess,'N')='N'  GROUP BY Trs_MultiPrs_Grn3.DeptID, Trs_MultiPrs_Grn1.GRNDate,Trs_MultiPrs_Grn1.DocNo,Trs_MultiPrs_Grn1.Finyear,Trs_MultiPrs_Grn2.PartyID,StockTable_2.OrdID,Trs_MultiPrs_Grn3.StyleNo, Trs_MultiPrs_Grn2.PartyDCref,ProcessType,GRNType,Trs_MultiPrs_Grn1.ID, Trs_MultiPrs_Grn1.Coycode,ISNULL(Mas_Count_2.CountName, '') , ISNULL(Mas_Color_5.ColorDesc, ''),ISNULL(Mas_Mill_2.ShortMill, ''),ISNULL(Mas_Fabric_2.Fabdesc, ''),ISNULL(Mas_Fabric_2.Fabid, ''), StockTable_2.Gsm,StockTable_2.GG, StockTable_2.ll, ISNULL(Mas_Dia_2.Dia,'') ,ISNULL(Mas_Size_5.SizeDesc, ''), StockTable_2.LotNo, StockTable_2.YF, ISNULL(OrdSizeMas_5.SNo, 0),Isnull(Mas_Design.DesignDesc,''),Mas_Dept.RecMethod,IsNull(remark,'') /*Comment Break */  UNION ALL SELECT     '2' AS Trn, Trs_MultiPrs_Grn2.DeptID, Trs_MultiPrs_Grn1.GRNDate, 'X'+RTRIM(Trs_MultiPrs_Grn1.DocNo) + '/' + RTRIM(Trs_MultiPrs_Grn1.Finyear) AS Doc, Trs_MultiPrs_Grn2.PartyID   as Party, Trs_MultiPrs_Grn3.OrdId,Trs_MultiPrs_Grn3.StyleNo, Sum(Trs_MultiPrs_Grn3.RBag) as RBag, Sum(Trs_MultiPrs_Grn3.RecKgs) As RecKgs,Sum(Trs_MultiPrs_Grn3.Recmtr) As RecMtr, '' AS Pdcref, 'Process Issue' AS trs,  Trs_MultiPrs_Grn1.ID, Trs_MultiPrs_Grn1.Coycode, ISNULL(Mas_Count.CountName, '') AS Countname,  ISNULL(Mas_Color_1.ColorDesc, '')  AS Color, ISNULL(Mas_Mill.ShortMill, '') AS Mill, ISNULL(Mas_Fabric.Fabdesc, '') AS Fabdesc,ISNULL(Mas_Fabric.Fabid, '') AS Fabid,  StockTable.Gsm, StockTable.GG, StockTable.ll, ISNULL(Mas_Dia.Dia, '') AS Dia, '' AS Acc_Descr,  '' AS AccDescription, ISNULL(Mas_Size.SizeDesc, '') AS SizeDesc, StockTable.LotNo, StockTable.YF, ISNULL(OrdSizeMas.SNo, 0) AS SIZSLNO, '' AS OrdRef, '' AS GenItem, '' AS GenUOM, ISNULL(Trs_MultiPrs_Grn1.ProcessType, 'P') AS ProcessType,  '' As PartyUnit, 0 AS GpNo,  case when Trs_MultiPrs_Grn2.PartyID =0 then 'Buyer' else 'Party' end AS PartyBuyer, Isnull(Mas_Design.DesignDesc,'') As DesignDesc,0 As BalKgs,0 As BalPer,IsNull(remark,'') As Remark,0 as targetstageid FROM  Mas_Design RIGHT OUTER JOIN  Trs_MultiPrs_Grn1 INNER JOIN Trs_MultiPrs_Grn2 ON Trs_MultiPrs_Grn1.ID = Trs_MultiPrs_Grn2.ID  INNER JOIN Trs_MultiPrs_Grn3 ON Trs_MultiPrs_Grn1.Id=Trs_MultiPrs_Grn3.ID AND Trs_MultiPrs_Grn2.DeptID=Trs_MultiPrs_Grn3.DeptID  INNER JOIN StockTable ON Trs_MultiPrs_Grn3.StockID =  StockTable.StockID ON Mas_Design.DesignId = StockTable.PRINT_DESIGNID LEFT OUTER JOIN OrdSizeMas RIGHT OUTER JOIN Mas_Size ON  OrdSizeMas.SizeID = Mas_Size.SizeID ON StockTable.OrdID = OrdSizeMas.OrdID AND StockTable.Siz = Mas_Size.SizeID and  OrdSizeMas.StyleNo=Trs_MultiPrs_Grn3.StyleNo LEFT OUTER JOIN Mas_Dia ON StockTable.DiaID = Mas_Dia.DiaID LEFT OUTER JOIN Mas_Fabric ON  StockTable.FabID = Mas_Fabric.FabID LEFT OUTER JOIN Mas_Mill ON StockTable.MillID = Mas_Mill.MillID   LEFT OUTER JOIN Mas_Color as Mas_Color_1 ON StockTable.ColID = Mas_Color_1.ColID  LEFT OUTER JOIN Mas_Count ON StockTable.CntID = Mas_Count.CountID WHERE     Trs_MultiPrs_Grn2.OurDCID = 0 Group By  Trs_MultiPrs_Grn2.DeptID, Trs_MultiPrs_Grn1.GRNDate,Trs_MultiPrs_Grn1.DocNo,Trs_MultiPrs_Grn1.Finyear,Trs_MultiPrs_Grn2.PartyID , Trs_MultiPrs_Grn3.OrdId,Trs_MultiPrs_Grn3.StyleNo,Trs_MultiPrs_Grn1.ID, Trs_MultiPrs_Grn1.Coycode, ISNULL(Mas_Count.CountName, ''), ISNULL(Mas_Color_1.ColorDesc, '') ,ISNULL(Mas_Mill.ShortMill, ''),ISNULL(Mas_Fabric.Fabdesc, ''),ISNULL(Mas_Fabric.Fabid, ''), StockTable.Gsm, StockTable.GG, StockTable.ll, ISNULL(Mas_Dia.Dia, '') ,ISNULL(Mas_Size.SizeDesc, '') , StockTable.LotNo, StockTable.YF, ISNULL(OrdSizeMas.SNo, 0) ,Trs_MultiPrs_Grn1.ProcessType,Isnull(Mas_Design.DesignDesc,''),IsNull(remark,'') 